        // [5] 결과 목록을 String 배열로 바꾼다.
        return selectedTaskIds.toArray(String[]::new);
    }

    private static int compareTasks(
            int left,
            int right,
            String[] taskIds,
            int[] minutes,
            int[] urgency
    ) {
        // 앞의 비교 기준이 같을 때만 다음 기준을 확인한다.
        int byUrgency = Integer.compare(urgency[right], urgency[left]);
